// ServerInterface represents all server handlers.
type ServerInterface interface {
	// GetOIDCConfiguration OIDC discovery (base issuer)
	// (GET /.well-known/openid-configuration)
	GetOIDCConfiguration(w http.ResponseWriter, r *http.Request)
	// GetJWKS Issuer signing keys
	// (GET /jwks)
	GetJWKS(w http.ResponseWriter, r *http.Request)
	// GetTenantOIDCConfiguration OIDC discovery (per-tenant issuer `…/t/{tenant}`)
	// (GET /t/{tenant}/.well-known/openid-configuration)
	GetTenantOIDCConfiguration(w http.ResponseWriter, r *http.Request, tenant TenantPath)
	// GetTenantJWKS Per-tenant issuer signing keys (same key set)
	// (GET /t/{tenant}/jwks)
	GetTenantJWKS(w http.ResponseWriter, r *http.Request, tenant TenantPath)
	// ListAudit Query audit records
	// (GET /v1/audit)
	ListAudit(w http.ResponseWriter, r *http.Request, params ListAuditParams)
	// AppendAudit Append a batch of host audit records
	// (POST /v1/audit)
	AppendAudit(w http.ResponseWriter, r *http.Request)
	// GetAuditVerification Verify every audit chain
	// (GET /v1/audit/verification)
	GetAuditVerification(w http.ResponseWriter, r *http.Request)
	// GetCertificate Look up a node certificate by stable node ID
	// (GET /v1/certificates/{stableNodeID})
	GetCertificate(w http.ResponseWriter, r *http.Request, stableNodeID string, params GetCertificateParams)
	// ListDeployments List deployments
	// (GET /v1/deployments)
	ListDeployments(w http.ResponseWriter, r *http.Request, params ListDeploymentsParams)
	// CreateDeployment Deploy a workload (async), or preflight it with dryRun
	// (POST /v1/deployments)
	CreateDeployment(w http.ResponseWriter, r *http.Request, params CreateDeploymentParams)
	// DeleteDeployment Undeploy
	// (DELETE /v1/deployments/{id})
	DeleteDeployment(w http.ResponseWriter, r *http.Request, id DeploymentID, params DeleteDeploymentParams)
	// GetDeployment Read a deployment and its status
	// (GET /v1/deployments/{id})
	GetDeployment(w http.ResponseWriter, r *http.Request, id DeploymentID, params GetDeploymentParams)
	// GetDeploymentBundle Download the raw bundle
	// (GET /v1/deployments/{id}/bundle)
	GetDeploymentBundle(w http.ResponseWriter, r *http.Request, id DeploymentID)
	// CreateDeviceDeleteRun Run the scheduled device deletes now
	// (POST /v1/device-delete-runs)
	CreateDeviceDeleteRun(w http.ResponseWriter, r *http.Request)
	// GetHealthz Liveness
	// (GET /v1/healthz)
	GetHealthz(w http.ResponseWriter, r *http.Request)
	// ListHosts List hosts
	// (GET /v1/hosts)
	ListHosts(w http.ResponseWriter, r *http.Request, params ListHostsParams)
	// CreateHost Add a host and mint its single-use join key
	// (POST /v1/hosts)
	CreateHost(w http.ResponseWriter, r *http.Request)
	// DeleteHost Drain and remove a host
	// (DELETE /v1/hosts/{id})
	DeleteHost(w http.ResponseWriter, r *http.Request, id HostID, params DeleteHostParams)
	// GetHost Read a host
	// (GET /v1/hosts/{id})
	GetHost(w http.ResponseWriter, r *http.Request, id HostID, params GetHostParams)
	// RegisterHost Register or re-register a host (idempotent)
	// (PUT /v1/hosts/{id})
	RegisterHost(w http.ResponseWriter, r *http.Request, id HostID)
	// ListHostAssignments List the deployments assigned to a host
	// (GET /v1/hosts/{id}/assignments)
	ListHostAssignments(w http.ResponseWriter, r *http.Request, id HostID, params ListHostAssignmentsParams)
	// ReportHostStatus Heartbeat (replace the host's reported status)
	// (PUT /v1/hosts/{id}/status)
	ReportHostStatus(w http.ResponseWriter, r *http.Request, id HostID)
	// ListObjects List objects (with lineage)
	// (GET /v1/objects)
	ListObjects(w http.ResponseWriter, r *http.Request, params ListObjectsParams)
	// CreateObject Create an object (async mint)
	// (POST /v1/objects)
	CreateObject(w http.ResponseWriter, r *http.Request)
	// DeleteObject Kill an object
	// (DELETE /v1/objects/{id})
	DeleteObject(w http.ResponseWriter, r *http.Request, id ObjectID, params DeleteObjectParams)
	// GetObject Read an object (lineage, children, kill record)
	// (GET /v1/objects/{id})
	GetObject(w http.ResponseWriter, r *http.Request, id ObjectID, params GetObjectParams)
	// UpdateObject Update an object (JSON Merge Patch)
	// (PATCH /v1/objects/{id})
	UpdateObject(w http.ResponseWriter, r *http.Request, id ObjectID, params UpdateObjectParams)
	// GetObjectCertificate Read the object's node certificate
	// (GET /v1/objects/{id}/certificate)
	GetObjectCertificate(w http.ResponseWriter, r *http.Request, id ObjectID)
	// CreateObjectCredential Mint a single-use auth key for the object's node
	// (POST /v1/objects/{id}/credentials)
	CreateObjectCredential(w http.ResponseWriter, r *http.Request, id ObjectID, params CreateObjectCredentialParams)
	// GetStatus mgmt status
	// (GET /v1/status)
	GetStatus(w http.ResponseWriter, r *http.Request)
	// ListTenants List tenants
	// (GET /v1/tenants)
	ListTenants(w http.ResponseWriter, r *http.Request, params ListTenantsParams)
	// CreateTenant Create a tenant
	// (POST /v1/tenants)
	CreateTenant(w http.ResponseWriter, r *http.Request)
	// DeleteTenant Delete a tenant
	// (DELETE /v1/tenants/{id})
	DeleteTenant(w http.ResponseWriter, r *http.Request, id TenantID, params DeleteTenantParams)
	// GetTenant Read a tenant
	// (GET /v1/tenants/{id})
	GetTenant(w http.ResponseWriter, r *http.Request, id TenantID, params GetTenantParams)
	// UpdateTenant Update a tenant (JSON Merge Patch)
	// (PATCH /v1/tenants/{id})
	UpdateTenant(w http.ResponseWriter, r *http.Request, id TenantID, params UpdateTenantParams)
	// PurgeTenantObjects Purge terminal objects of a tenant
	// (DELETE /v1/tenants/{id}/objects)
	PurgeTenantObjects(w http.ResponseWriter, r *http.Request, id TenantID, params PurgeTenantObjectsParams)
	// CheckTenantWIF Verify a wif tenant's trust credentials (diagnostic)
	// (POST /v1/tenants/{id}/wif-check)
	CheckTenantWIF(w http.ResponseWriter, r *http.Request, id TenantID)
	// CreateVolumeKeyGrant Release a volume's dm-crypt data key to the lease holder
	// (POST /v1/volumes/{id}/keys)
	CreateVolumeKeyGrant(w http.ResponseWriter, r *http.Request, id VolumeID, params CreateVolumeKeyGrantParams)
	// WhoAmI Who the caller is, as mgmt sees it
	// (GET /v1/whoami)
	WhoAmI(w http.ResponseWriter, r *http.Request)
}

